"use client";
import { useState } from "react";
import { logActivity, resetDb, useSlice } from "@/lib/biz/db";
import { MERGE_FIELDS, type Campaign, type JStep, type JType, type Journey, type MContact, type Rule, type Segment, type Template, type Tpl } from "@/lib/biz/seed-mkt";
import { audience, campaignAudience, merge, rate, simulateMetrics, unknownFields } from "@/lib/biz/mkt-calc";
import { DEMO_NOW, DEMO_TODAY, addDays, downloadJson, emailOk, fmtDt, lastNMonths, monthKey, monthLabel, pct, uid } from "@/lib/biz/util";
import type { Branding } from "@/lib/types";
import { AppProviders, AreaIn, Badge, BarChart, BrandLogo, Btn, DataTable, DemoBadge, DemoLinks, Empty, FilterSelect, HBars, Kpi, KpiRow, Modal, Notice, PageHead, Panel, ResetButton, Segmented, SelectIn, Tabs, TextIn, Timeline, useConfirm, useToast, type Col } from "./kit";

/* Campaign studio: a violet, canvas-style workspace. Big section tabs, campaign cards with live email thumbnails, a side-by-side email editor, and a visual journey builder. */
const SECTIONS = [{ id: "campaigns", label: "Campaigns", hint: "Plan and send" }, { id: "audience", label: "Audience", hint: "Contacts and segments" }, { id: "templates", label: "Templates", hint: "Reusable emails" }, { id: "journeys", label: "Journeys", hint: "Automated flows" }, { id: "analytics", label: "Analytics", hint: "Simulated results" }];
const stTone = (s: string) => (s.startsWith("Sent") ? "green" : s === "Scheduled" ? "blue" : s === "Cancelled" ? "red" : "slate") as "green" | "blue" | "red" | "slate";
const SIM = "SIMULATED sample metrics: no email was sent, and no real recipient opened or clicked anything.";

export default function MarketingApp({ branding }: { branding: Branding }) {
  return (
    <AppProviders className="bg-violet-50 text-slate-800" note="Demonstration marketing software. No emails are sent: campaign execution is a simulated workflow and every delivery, open and click figure is simulated sample data. Contacts are fictional. Stored only in this browser (localStorage); no server.">
      <Studio branding={branding} />
    </AppProviders>
  );
}
function Studio({ branding }: { branding: Branding }) {
  const [screen, setScreen] = useState("campaigns"); const [cid, setCid] = useState<string | null>(null); const { mkt } = useM();
  const open = (id: string) => { setCid(id); setScreen("campaigns"); };
  return (<>
    <header className="no-print border-b border-violet-200 bg-white">
      <div className="flex flex-wrap items-center gap-x-5 gap-y-2 px-5 py-3">
        <BrandLogo branding={branding} dark={false} height={28} />
        <div className="border-l border-violet-200 pl-5"><h1 className="font-display text-xl font-semibold leading-tight text-violet-950">NorthPeak Engage · Campaign studio</h1><p className="text-sm text-slate-600">Marketing automation · all sending is simulated</p></div>
        <div className="ml-auto flex flex-wrap items-center gap-2"><DemoBadge text="Demonstration · simulated sending" /><ResetButton onReset={() => resetDb(["mkt"])} className="rounded-md border border-slate-300 px-3 py-1.5 text-sm font-medium text-slate-700 hover:border-violet-500" /><span className="flex gap-2 text-slate-700 [&_a]:border-slate-300"><DemoLinks compact /></span></div>
      </div>
      <nav aria-label="Studio sections" className="grid grid-cols-2 gap-2 px-4 pb-3 sm:grid-cols-3 lg:grid-cols-5">
        {SECTIONS.map((s) => <button key={s.id} type="button" data-nav={s.id} aria-current={screen === s.id ? "page" : undefined} onClick={() => { setScreen(s.id); setCid(null); }} className={`rounded-xl border-2 px-4 py-2 text-left ${screen === s.id ? "border-violet-600 bg-violet-600 text-white" : "border-violet-100 bg-violet-50 text-violet-950 hover:border-violet-400"}`}><span className="block text-[16px] font-semibold">{s.label}{s.id === "campaigns" && <span className="ml-2 text-[13px] opacity-80">{mkt.campaigns.length}</span>}{s.id === "journeys" && <span className="ml-2 text-[13px] opacity-80">{mkt.journeys.length}</span>}</span><span className={`block text-sm ${screen === s.id ? "text-violet-100" : "text-slate-600"}`}>{s.hint}</span></button>)}
      </nav>
    </header>
    <main className="min-w-0 flex-1 p-4 sm:p-6" id="app-main">
      {screen === "campaigns" && (cid ? <Editor id={cid} back={() => setCid(null)} /> : <Campaigns open={open} />)}
      {screen === "audience" && <AudienceSection />}
      {screen === "templates" && <Templates open={open} />}
      {screen === "journeys" && <Journeys />}
      {screen === "analytics" && <AnalyticsSection open={open} />}
    </main>
  </>);
}
const useM = () => { const [mkt, setMkt] = useSlice("mkt"); const segName = (id: string) => mkt.segments.find((s) => s.id === id)?.name ?? "—"; return { mkt, setMkt, segName }; };
function AudienceSection() { const [v, setV] = useState("contacts"); return (<><div className="mb-3"><Segmented label="Audience view" value={v} onChange={setV} options={[{ id: "contacts", label: "Contact lists" }, { id: "segments", label: "Customer segments" }]} /></div>{v === "contacts" ? <Contacts /> : <Segments />}</>); }
function AnalyticsSection({ open }: { open(id: string): void }) { const [v, setV] = useState("performance"); return (<><div className="mb-3"><Segmented label="Analytics view" value={v} onChange={setV} options={[{ id: "performance", label: "Performance" }, { id: "calendar", label: "Calendar" }]} /></div>{v === "performance" ? <Analytics open={open} /> : <Calendar open={open} />}</>); }

/* ───────── Campaign cards ───────── */
function Thumb({ t, c }: { t: Template; c: Pick<MContact, "name" | "company" | "industry"> }) {
  return (<div className="pointer-events-none h-36 overflow-hidden rounded-lg border border-violet-100 bg-white" aria-hidden><div className="border-b border-slate-200 bg-slate-50 px-3 py-1 text-sm font-semibold text-slate-700">{merge(t.subject, c) || "(no subject)"}</div><div className="px-3 py-2"><div className="mb-1.5 h-1 w-10 rounded bg-violet-500" /><p className="font-display text-[15px] font-semibold leading-tight text-slate-900">{merge(t.heading, c)}</p><p className="mt-1 line-clamp-3 text-sm text-slate-600">{merge(t.body, c).replace(/\n+/g, " ")}</p></div></div>);
}
function Campaigns({ open }: { open(id: string): void }) {
  const { mkt, setMkt, segName } = useM(); const toast = useToast(); const [status, setStatus] = useState(""); const [form, setForm] = useState(false); const [name, setName] = useState(""); const [seg, setSeg] = useState(mkt.segments[0]?.id ?? ""); const [err, setErr] = useState("");
  const rows = mkt.campaigns.filter((c) => !status || c.status === status); const sample = mkt.contacts[0];
  return (<><PageHead title="Campaigns" sub="Each card shows the email as a recipient would see it. Open one to edit, preview, schedule or run it as a simulation." actions={<><FilterSelect label="Status" value={status} onChange={setStatus} options={["Draft", "Scheduled", "Sent (simulated)", "Cancelled"]} /><Btn kind="primary" onClick={() => setForm(true)} testid="new-campaign">+ New campaign</Btn></>} />
    <ul className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3" data-testid="campaign-cards">{rows.map((c) => { const aud = campaignAudience(c, mkt.contacts, mkt.segments); return (<li key={c.id}><button type="button" onClick={() => open(c.id)} className="flex h-full w-full flex-col rounded-2xl border-2 border-violet-100 bg-white p-4 text-left shadow-sm hover:border-violet-500">
      <Thumb t={c.template} c={sample} />
      <span className="mt-3 flex items-start justify-between gap-2"><span className="font-display text-lg font-semibold leading-tight text-slate-900">{c.name}</span><Badge tone={stTone(c.status)}>{c.status}</Badge></span>
      <span className="mt-1 text-[15px] text-slate-600">{c.description}</span>
      <span className="mt-auto pt-3 text-sm text-slate-600">{segName(c.segmentId)} · {aud.sendable.length} sendable · {c.scheduledFor ? fmtDt(c.scheduledFor) : "not scheduled"}</span></button></li>); })}
      {rows.length === 0 && <li className="sm:col-span-2 xl:col-span-3"><Empty>No campaigns match this filter.</Empty></li>}</ul>
    {form && <Modal title="New campaign" small onClose={() => setForm(false)} footer={<><Btn onClick={() => setForm(false)}>Cancel</Btn><Btn kind="primary" testid="create-campaign" onClick={() => { if (name.trim().length < 3) return setErr("Name the campaign (3+ characters)."); if (mkt.campaigns.some((c) => c.name.toLowerCase() === name.trim().toLowerCase())) return setErr("A campaign with this name already exists."); const id = uid("cp"); setMkt((s) => ({ ...s, campaigns: [{ id, name: name.trim(), description: "", segmentId: seg, status: "Draft", scheduledFor: "", createdAt: DEMO_TODAY, template: { subject: "", preheader: "", heading: "", body: "Hi {{first_name}},\n\n", cta: "Learn more", url: "https://example.com/northpeak-demo" }, execution: [], metrics: null }, ...s.campaigns] })); logActivity("Marketing", `Campaign created: ${name.trim()}`); toast("Campaign created as a draft"); setForm(false); setName(""); open(id); }}>Create</Btn></>}>
      <div className="grid gap-3"><TextIn label="Campaign name" value={name} onChange={(e) => setName(e.target.value)} /><SelectIn label="Segment" value={seg} onChange={(e) => setSeg(e.target.value)} options={mkt.segments.map((s) => ({ value: s.id, label: s.name }))} /></div>{err && <p role="alert" className="mt-2 text-sm text-red-600">{err}</p>}</Modal>}</>);
}

/* ───────── Templates library ───────── */
function TemplateForm({ existing, onSave, onClose }: { existing?: Tpl; onSave(t: Omit<Tpl, "id">): void; onClose(): void }) {
  const [f, setF] = useState({ name: existing?.name ?? "", category: existing?.category ?? "Newsletter", subject: existing?.subject ?? "", preheader: existing?.preheader ?? "A short update from NorthPeak", heading: existing?.heading ?? "", body: existing?.body ?? "Hi {{first_name}},\n\n", cta: existing?.cta ?? "Learn more", url: existing?.url ?? "https://example.com/northpeak-demo" }); const [err, setErr] = useState("");
  const unk = unknownFields(f);
  return (<Modal title={existing ? `Edit template: ${existing.name}` : "New template"} wide onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" testid="save-template" onClick={() => { if (f.name.trim().length < 3) return setErr("Name the template (3+ characters)."); if (f.subject.trim().length < 3 || f.body.trim().length < 10) return setErr("Add a subject and a body (10+ characters)."); if (unk.length) return setErr(`Unknown merge field ${unk[0]}. Use ${MERGE_FIELDS.join(", ")}.`); onSave({ ...f, name: f.name.trim() }); }}>Save template</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><TextIn label="Template name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} /><SelectIn label="Category" value={f.category} onChange={(e) => setF({ ...f, category: e.target.value })} options={["Newsletter", "Announcement", "Onboarding", "Follow-up", "Event", "Other"]} />
      <TextIn label="Subject" className="sm:col-span-2" value={f.subject} onChange={(e) => setF({ ...f, subject: e.target.value })} /><TextIn label="Heading" className="sm:col-span-2" value={f.heading} onChange={(e) => setF({ ...f, heading: e.target.value })} /><AreaIn label="Body" className="sm:col-span-2" rows={6} value={f.body} onChange={(e) => setF({ ...f, body: e.target.value })} /><TextIn label="Button text" value={f.cta} onChange={(e) => setF({ ...f, cta: e.target.value })} /><TextIn label="Button link" value={f.url} onChange={(e) => setF({ ...f, url: e.target.value })} /><p className="text-sm text-slate-600 sm:col-span-2">Merge fields: {MERGE_FIELDS.join(", ")}</p></div>{err && <p role="alert" className="mt-2 text-sm text-red-600">{err}</p>}</Modal>);
}
function Templates({ open }: { open(id: string): void }) {
  const { mkt, setMkt } = useM(); const toast = useToast(); const confirm = useConfirm(); const [form, setForm] = useState<Tpl | "new" | null>(null); const [use, setUse] = useState<Tpl | null>(null); const [target, setTarget] = useState(""); const [cat, setCat] = useState(""); const sample = mkt.contacts[0];
  const rows = mkt.templates.filter((t) => !cat || t.category === cat); const usable = mkt.campaigns.filter((c) => c.status === "Draft" || c.status === "Scheduled");
  return (<><PageHead title="Templates" sub="Reusable email designs with merge fields. Apply one to a draft campaign, or build a journey step from it." actions={<><FilterSelect label="Category" value={cat} onChange={setCat} options={[...new Set(mkt.templates.map((t) => t.category))]} /><Btn kind="primary" onClick={() => setForm("new")} testid="new-template">+ New template</Btn></>} />
    <ul className="grid gap-4 sm:grid-cols-2 xl:grid-cols-3" data-testid="template-cards">{rows.map((t) => <li key={t.id} className="flex flex-col rounded-2xl border-2 border-violet-100 bg-white p-4 shadow-sm"><Thumb t={t} c={sample} /><div className="mt-3 flex items-start justify-between gap-2"><h3 className="font-display text-lg font-semibold">{t.name}</h3><Badge tone="violet">{t.category}</Badge></div>
      <div className="mt-auto flex flex-wrap gap-2 pt-3"><Btn small kind="primary" onClick={() => { setUse(t); setTarget(usable[0]?.id ?? ""); }} aria-label={`Use ${t.name}`}>Use in campaign</Btn><Btn small onClick={() => setForm(t)} aria-label={`Edit ${t.name}`}>Edit</Btn><Btn small onClick={() => { setMkt((s) => ({ ...s, templates: [...s.templates, { ...t, id: uid("tp"), name: `${t.name} (copy)` }] })); toast("Template duplicated"); }}>Duplicate</Btn>
        <Btn small kind="danger" aria-label={`Delete ${t.name}`} onClick={async () => { const inUse = mkt.journeys.some((j) => j.steps.some((s) => s.templateId === t.id)); if (inUse) return toast("This template is used by a journey. Change the journey step first.", "red"); if (await confirm(`Delete template “${t.name}”?`)) { setMkt((s) => ({ ...s, templates: s.templates.filter((x) => x.id !== t.id) })); toast("Template deleted", "amber"); } }}>Delete</Btn></div></li>)}</ul>
    {form && <TemplateForm existing={form === "new" ? undefined : form} onClose={() => setForm(null)} onSave={(rec) => { if (form === "new") setMkt((s) => ({ ...s, templates: [...s.templates, { id: uid("tp"), ...rec }] })); else setMkt((s) => ({ ...s, templates: s.templates.map((x) => (x.id === form.id ? { ...x, ...rec } : x)) })); toast("Template saved"); setForm(null); }} />}
    {use && <Modal title={`Use “${use.name}” in a campaign`} small onClose={() => setUse(null)} footer={<><Btn onClick={() => setUse(null)}>Cancel</Btn><Btn kind="primary" disabled={!target} testid="apply-template" onClick={() => { setMkt((s) => ({ ...s, campaigns: s.campaigns.map((c) => (c.id === target ? { ...c, template: { subject: use.subject, preheader: use.preheader, heading: use.heading, body: use.body, cta: use.cta, url: use.url } } : c)) })); toast("Template applied to the campaign"); setUse(null); open(target); }}>Apply and open</Btn></>}>
      {usable.length ? <SelectIn label="Campaign (draft or scheduled)" value={target} onChange={(e) => setTarget(e.target.value)} options={usable.map((c) => ({ value: c.id, label: `${c.name} (${c.status})` }))} /> : <Empty>No draft or scheduled campaigns. Create a campaign first.</Empty>}<p className="mt-2 text-sm text-slate-600">This replaces the campaign&apos;s current email content.</p></Modal>}</>);
}

/* ───────── Journey builder ───────── */
const STEP_META: Record<JType, { label: string; icon: string; tone: string }> = { entry: { label: "Entry", icon: "●", tone: "border-emerald-500 bg-emerald-50" }, email: { label: "Send email", icon: "✉", tone: "border-violet-500 bg-violet-50" }, wait: { label: "Wait", icon: "⏱", tone: "border-slate-400 bg-slate-50" }, check: { label: "Check engagement", icon: "?", tone: "border-amber-500 bg-amber-50" }, followup: { label: "Follow-up email", icon: "↻", tone: "border-sky-500 bg-sky-50" } };
const journeyIssue = (j: Journey): string => {
  if (j.steps[0]?.type !== "entry") return "A journey must start with an entry step.";
  for (let i = 0; i < j.steps.length; i++) { const s = j.steps[i];
    if ((s.type === "email" || s.type === "followup") && !s.templateId) return `Step ${i + 1} (${STEP_META[s.type].label}) needs a template.`;
    if (s.type === "wait" && !(Number(s.days) >= 1)) return `Step ${i + 1} (Wait) needs at least 1 day.`;
    if (s.type === "check" && !j.steps.slice(0, i).some((x) => x.type === "email" || x.type === "followup")) return `Step ${i + 1} (Check engagement) must come after an email.`;
    if (s.type === "followup" && !j.steps.slice(0, i).some((x) => x.type === "check")) return `Step ${i + 1} (Follow-up) should come after a Check engagement step.`; }
  return "";
};
function simulateJourney(j: Journey, sendable: number): { counts: Record<string, number>; engaged: number } {
  const counts: Record<string, number> = {}; let flow = sendable; let engaged = 0;
  for (const s of j.steps) { if (s.type === "entry") counts[s.id] = flow; else if (s.type === "email") { const m = simulateMetrics(flow, `${j.id}${s.id}`); counts[s.id] = m.delivered; flow = m.delivered; } else if (s.type === "wait") counts[s.id] = flow;
    else if (s.type === "check") { const m = simulateMetrics(flow, `${j.id}${s.id}c`); const yes = s.criterion === "clicked" ? Math.round(m.clicked * 1.6) : m.opened; engaged = Math.min(flow, yes); counts[s.id] = flow; flow = flow - engaged; }
    else { const m = simulateMetrics(flow, `${j.id}${s.id}`); counts[s.id] = flow; flow = m.delivered; } }
  return { counts, engaged };
}
function Journeys() {
  const { mkt, setMkt } = useM(); const toast = useToast(); const confirm = useConfirm(); const [jid, setJid] = useState(mkt.journeys[0]?.id ?? ""); const [stepId, setStepId] = useState<string | null>(null); const [newName, setNewName] = useState(""); const [form, setForm] = useState(false);
  const j = mkt.journeys.find((x) => x.id === jid) ?? mkt.journeys[0]; const step = j?.steps.find((s) => s.id === stepId);
  const patch = (fn: (j: Journey) => Journey) => setMkt((s) => ({ ...s, journeys: s.journeys.map((x) => (x.id === j!.id ? { ...fn(x), result: null } : x)) }));
  if (!j) return <><PageHead title="Journeys" actions={<Btn kind="primary" onClick={() => setForm(true)}>+ New journey</Btn>} /><Empty>No journeys yet.</Empty></>;
  const issue = journeyIssue(j); const aud = audience(mkt.contacts, mkt.segments.find((s) => s.id === j.segmentId)); const tplName = (id?: string) => mkt.templates.find((t) => t.id === id)?.name ?? "No template chosen";
  const add = (type: JType) => { const s: JStep = { id: uid("js"), type, ...(type === "wait" ? { days: 2 } : {}), ...(type === "check" ? { criterion: "opened" as const } : {}), ...(type === "email" || type === "followup" ? { templateId: mkt.templates[0]?.id } : {}) }; patch((x) => ({ ...x, steps: [...x.steps, s] })); setStepId(s.id); };
  const move = (id: string, d: -1 | 1) => patch((x) => { const i = x.steps.findIndex((s) => s.id === id), k = i + d; if (i < 1 || k < 1 || k >= x.steps.length) return x; const steps = [...x.steps]; [steps[i], steps[k]] = [steps[k], steps[i]]; return { ...x, steps }; });
  const run = () => { if (issue) return toast(issue, "red"); const r = simulateJourney(j, aud.sendable.length); setMkt((s) => ({ ...s, journeys: s.journeys.map((x) => (x.id === j.id ? { ...x, result: { at: DEMO_NOW, ...r } } : x)) })); logActivity("Marketing", `Journey simulated: ${j.name} (${aud.sendable.length} contacts)`); toast("Journey simulated. Counts on each step are sample figures; nothing was sent."); };
  return (<>
    <PageHead title="Journeys" sub="Build an automated flow from steps, then run it as a simulation to see how many contacts reach each stage." actions={<><SelectIn label="Journey" value={j.id} onChange={(e) => { setJid(e.target.value); setStepId(null); }} options={mkt.journeys.map((x) => ({ value: x.id, label: x.name }))} className="min-w-52" /><Btn kind="primary" onClick={() => setForm(true)} testid="new-journey">+ New journey</Btn></>} />
    <Notice tone="blue">Simulation only: no email is sent and the counts below are sample figures generated in your browser.</Notice>
    <div className="mt-4 grid gap-4 xl:grid-cols-[minmax(0,1fr)_330px]">
      <section aria-label="Journey canvas" className="rounded-2xl border-2 border-dashed border-violet-300 bg-white p-4 [background-image:radial-gradient(#ddd6fe_1px,transparent_1px)] [background-size:20px_20px]">
        <div className="mb-3 flex flex-wrap items-center gap-2 rounded-lg bg-white/90 p-2"><span className="text-[15px] font-semibold text-slate-700">Add step:</span>{(["email", "wait", "check", "followup"] as JType[]).map((t) => <Btn key={t} small onClick={() => add(t)} testid={`add-${t}`}>+ {STEP_META[t].label}</Btn>)}
          <span className="ml-auto flex items-center gap-2"><Btn small onClick={run} kind="primary" testid="run-journey">Run simulation</Btn></span></div>
        <ol className="flex flex-nowrap items-start gap-x-2 overflow-x-auto pb-3" data-testid="journey-flow">{j.steps.map((s, i) => { const m = STEP_META[s.type]; const n = j.result?.counts[s.id];
          return (<li key={s.id} className="flex shrink-0 items-start gap-2"><div className="w-52">
            <button type="button" onClick={() => setStepId(s.id)} aria-pressed={stepId === s.id} data-testid={`step-${s.type}`} className={`block w-full rounded-xl border-2 p-3 text-left shadow-sm ${m.tone} ${stepId === s.id ? "ring-2 ring-violet-600" : ""}`}>
              <span className="flex items-center gap-2 text-[15px] font-semibold text-slate-900"><span aria-hidden className="flex h-7 w-7 items-center justify-center rounded-full bg-white text-sm">{m.icon}</span>{i + 1}. {m.label}</span>
              <span className="mt-1 block text-[15px] text-slate-700">{s.type === "email" || s.type === "followup" ? tplName(s.templateId) : s.type === "wait" ? `Wait ${s.days} day${s.days === 1 ? "" : "s"}` : s.type === "check" ? `Did they ${s.criterion === "clicked" ? "click" : "open"} the email?` : `${aud.sendable.length} sendable contacts`}</span>
              {n != null && <span className="mt-1 block text-sm font-semibold text-violet-800" data-testid={`count-${s.type}`}>Simulated: {n} contacts</span>}</button>
            {s.type === "check" && <p className="mt-1 rounded-md bg-emerald-100 px-2 py-1 text-sm text-emerald-900">Yes → goal reached, leave the journey{j.result ? ` (${j.result.engaged})` : ""}<br /><span className="text-slate-700">No → continue to the next step</span></p>}</div>
            {i < j.steps.length - 1 && <span aria-hidden className="mt-6 text-2xl text-violet-400">→</span>}</li>); })}</ol>
        {j.result && <p className="mt-4 rounded-lg bg-violet-50 p-3 text-[15px] text-violet-950" data-testid="journey-result">Simulated run at {fmtDt(j.result.at)}: {j.result.counts[j.steps[0].id]} contacts entered; {j.result.engaged} met the engagement goal and left early.</p>}
        {issue && <p role="alert" className="mt-3 text-[15px] font-medium text-red-700" data-testid="journey-issue">Fix before running: {issue}</p>}
      </section>
      <aside aria-label="Step settings" className="space-y-4">
        <Panel title="Journey"><div className="grid gap-3"><TextIn label="Name" value={j.name} onChange={(e) => patch((x) => ({ ...x, name: e.target.value }))} /><AreaIn label="Description" value={j.description} onChange={(e) => patch((x) => ({ ...x, description: e.target.value }))} /><SelectIn label="Audience segment" value={j.segmentId} onChange={(e) => patch((x) => ({ ...x, segmentId: e.target.value }))} options={mkt.segments.map((sg) => ({ value: sg.id, label: `${sg.name} (${audience(mkt.contacts, sg).sendable.length})` }))} />
          <Btn kind="danger" onClick={async () => { if (await confirm(`Delete journey “${j.name}”?`)) { setMkt((s) => ({ ...s, journeys: s.journeys.filter((x) => x.id !== j.id) })); setJid(""); setStepId(null); toast("Journey deleted", "amber"); } }}>Delete journey</Btn></div></Panel>
        <Panel title={step ? `Step settings: ${STEP_META[step.type].label}` : "Step settings"}>{step ? <div className="grid gap-3">
          {(step.type === "email" || step.type === "followup") && <SelectIn label="Email template" value={step.templateId ?? ""} onChange={(e) => patch((x) => ({ ...x, steps: x.steps.map((s) => (s.id === step.id ? { ...s, templateId: e.target.value } : s)) }))} options={[{ value: "", label: "Choose a template…" }, ...mkt.templates.map((t) => ({ value: t.id, label: t.name }))]} />}
          {step.type === "wait" && <TextIn label="Days to wait" type="number" min={1} max={60} value={step.days ?? 1} onChange={(e) => patch((x) => ({ ...x, steps: x.steps.map((s) => (s.id === step.id ? { ...s, days: Math.max(0, Number(e.target.value) || 0) } : s)) }))} />}
          {step.type === "check" && <SelectIn label="Engagement goal" value={step.criterion ?? "opened"} onChange={(e) => patch((x) => ({ ...x, steps: x.steps.map((s) => (s.id === step.id ? { ...s, criterion: e.target.value as "opened" | "clicked" } : s)) }))} options={[{ value: "opened", label: "Opened the email" }, { value: "clicked", label: "Clicked a link" }]} />}
          {step.type === "entry" && <p className="text-[15px] text-slate-600">Contacts enter from the audience segment above. Unsubscribed and bounced contacts are always excluded.</p>}
          {step.type !== "entry" && <div className="flex gap-2"><Btn small onClick={() => move(step.id, -1)} aria-label="Move step earlier">← Earlier</Btn><Btn small onClick={() => move(step.id, 1)} aria-label="Move step later">Later →</Btn><Btn small kind="danger" onClick={() => { patch((x) => ({ ...x, steps: x.steps.filter((s) => s.id !== step.id) })); setStepId(null); toast("Step removed", "amber"); }}>Remove</Btn></div>}</div> : <p className="text-[15px] text-slate-600">Select a step on the canvas to edit it. Use “Add step” to extend the journey.</p>}</Panel>
      </aside></div>
    {form && <Modal title="New journey" small onClose={() => setForm(false)} footer={<><Btn onClick={() => setForm(false)}>Cancel</Btn><Btn kind="primary" testid="create-journey" onClick={() => { if (newName.trim().length < 3) return toast("Name the journey (3+ characters).", "red"); const id = uid("jr"); setMkt((s) => ({ ...s, journeys: [...s.journeys, { id, name: newName.trim(), description: "", segmentId: s.segments[0]?.id ?? "", result: null, steps: [{ id: uid("js"), type: "entry" }] }] })); setJid(id); setStepId(null); setForm(false); setNewName(""); toast("Journey created. Add steps to build the flow."); }}>Create</Btn></>}><TextIn label="Journey name" value={newName} onChange={(e) => setNewName(e.target.value)} /></Modal>}
  </>);
}

function ContactForm({ existing, onClose, onSave }: { existing?: MContact; onClose(): void; onSave(c: Omit<MContact, "id" | "created" | "lastEngaged">): void }) {
  const { mkt } = useM(); const [f, setF] = useState({ name: existing?.name ?? "", email: existing?.email ?? "", company: existing?.company ?? "", industry: existing?.industry ?? "", country: existing?.country ?? "", tags: (existing?.tags ?? []).join(", "), status: existing?.status ?? ("Subscribed" as MContact["status"]), source: existing?.source ?? "Website", score: String(existing?.score ?? 40), lists: existing?.lists ?? [] }); const [err, setErr] = useState<Record<string, string>>({});
  const save = () => { const e: Record<string, string> = {}; if (f.name.trim().split(" ").length < 2) e.name = "Enter first and last name"; if (!emailOk(f.email)) e.email = "Enter a valid email"; else if (mkt.contacts.some((c) => c.email.toLowerCase() === f.email.trim().toLowerCase() && c.id !== existing?.id)) e.email = "A contact with this email already exists"; if (!f.company.trim()) e.company = "Enter a company"; if (!(Number(f.score) >= 0 && Number(f.score) <= 100)) e.score = "Score is 0–100"; setErr(e); if (!Object.keys(e).length) onSave({ ...f, name: f.name.trim(), email: f.email.trim(), score: Number(f.score), tags: f.tags.split(",").map((t) => t.trim().toLowerCase()).filter(Boolean) }); };
  return (<Modal title={existing ? `Edit ${existing.name}` : "New contact"} wide onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" onClick={save} testid="save-mcontact">Save contact</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><TextIn label="Full name" value={f.name} onChange={(e) => setF({ ...f, name: e.target.value })} error={err.name} /><TextIn label="Email" value={f.email} onChange={(e) => setF({ ...f, email: e.target.value })} error={err.email} /><TextIn label="Company" value={f.company} onChange={(e) => setF({ ...f, company: e.target.value })} error={err.company} /><TextIn label="Industry" value={f.industry} onChange={(e) => setF({ ...f, industry: e.target.value })} /><TextIn label="Country" value={f.country} onChange={(e) => setF({ ...f, country: e.target.value })} /><TextIn label="Tags (comma separated)" value={f.tags} onChange={(e) => setF({ ...f, tags: e.target.value })} />
      <SelectIn label="Status" value={f.status} onChange={(e) => setF({ ...f, status: e.target.value as MContact["status"] })} options={["Subscribed", "Unsubscribed", "Bounced"]} /><TextIn label="Engagement score (0–100)" type="number" value={f.score} onChange={(e) => setF({ ...f, score: e.target.value })} error={err.score} />
      <fieldset className="sm:col-span-2"><legend className="mb-1 text-xs font-semibold text-slate-600">Lists</legend><div className="flex flex-wrap gap-3">{mkt.lists.map((l) => <label key={l.id} className="flex items-center gap-1.5 text-sm"><input type="checkbox" checked={f.lists.includes(l.id)} onChange={(e) => setF({ ...f, lists: e.target.checked ? [...f.lists, l.id] : f.lists.filter((x) => x !== l.id) })} />{l.name}</label>)}</div></fieldset></div></Modal>);
}
function Contacts() {
  const { mkt, setMkt } = useM(); const toast = useToast(); const confirm = useConfirm(); const [tab, setTab] = useState("contacts"); const [form, setForm] = useState<MContact | "new" | null>(null); const [list, setList] = useState(""); const [status, setStatus] = useState(""); const [ind, setInd] = useState(""); const [nl, setNl] = useState("");
  const rows = mkt.contacts.filter((c) => (!list || c.lists.includes(list)) && (!status || c.status === status) && (!ind || c.industry === ind));
  const cols: Col<MContact>[] = [{ key: "name", label: "Contact", render: (c) => <span><span className="font-medium text-slate-900">{c.name}</span><span className="block text-xs text-slate-500">{c.email}</span></span>, value: (c) => c.name }, { key: "company", label: "Company" }, { key: "industry", label: "Industry" }, { key: "country", label: "Country" }, { key: "tags", label: "Tags", value: (c) => c.tags.join(" "), render: (c) => <span className="flex flex-wrap gap-1">{c.tags.map((t) => <Badge key={t}>{t}</Badge>)}</span> }, { key: "score", label: "Score", align: "right" }, { key: "status", label: "Status", render: (c) => <Badge tone={c.status === "Subscribed" ? "green" : c.status === "Bounced" ? "red" : "amber"}>{c.status}</Badge> },
    { key: "act", label: "", noSort: true, noCsv: true, render: (c) => <div className="flex gap-1"><Btn small onClick={() => setForm(c)} aria-label={`Edit ${c.name}`}>Edit</Btn><Btn small kind="danger" aria-label={`Delete ${c.name}`} onClick={async () => { if (await confirm(`Delete ${c.name}?`)) { setMkt((s) => ({ ...s, contacts: s.contacts.filter((x) => x.id !== c.id) })); toast("Contact deleted", "amber"); } }}>✕</Btn></div> }];
  return (<><PageHead title="Contact lists" sub={`${mkt.contacts.length} contacts. Unsubscribed and bounced contacts are never included in a campaign run.`} actions={<Btn kind="primary" onClick={() => setForm("new")} testid="new-mcontact">+ New contact</Btn>} />
    <Tabs value={tab} onChange={setTab} tabs={[{ id: "contacts", label: "Contacts", count: rows.length }, { id: "lists", label: "Lists", count: mkt.lists.length }]} />
    <div className="mt-3">{tab === "contacts" ? <DataTable rows={rows} columns={cols} rowKey={(c) => c.id} exportName="marketing-contacts" searchPlaceholder="Search contacts…" pageSize={12} testid="mcontact-table" toolbar={<><FilterSelect label="List" value={list} onChange={setList} options={mkt.lists.map((l) => ({ value: l.id, label: l.name }))} /><FilterSelect label="Status" value={status} onChange={setStatus} options={["Subscribed", "Unsubscribed", "Bounced"]} /><FilterSelect label="Industry" value={ind} onChange={setInd} options={[...new Set(mkt.contacts.map((c) => c.industry))].sort()} /></>} /> : (
      <div className="grid gap-3 md:grid-cols-2">{mkt.lists.map((l) => <Panel key={l.id} title={l.name} actions={<Btn small onClick={() => { setList(l.id); setTab("contacts"); }}>View contacts</Btn>}><p className="text-sm text-slate-500">{l.description}</p><p className="mt-2 font-display text-2xl">{mkt.contacts.filter((c) => c.lists.includes(l.id)).length}<span className="text-xs text-slate-500"> contacts</span></p></Panel>)}
        <Panel title="New list"><div className="flex gap-2"><input aria-label="New list name" value={nl} onChange={(e) => setNl(e.target.value)} placeholder="List name" className="w-full rounded-md border border-slate-300 px-2 py-1.5 text-sm" /><Btn kind="primary" testid="add-list" onClick={() => { if (nl.trim().length < 3) return toast("Enter a list name (3+ characters)", "red"); if (mkt.lists.some((l) => l.name.toLowerCase() === nl.trim().toLowerCase())) return toast("That list already exists", "red"); setMkt((s) => ({ ...s, lists: [...s.lists, { id: uid("l"), name: nl.trim(), description: "Custom list" }] })); setNl(""); toast("List created"); }}>Create</Btn></div></Panel></div>)}</div>
    {form && <ContactForm existing={form === "new" ? undefined : form} onClose={() => setForm(null)} onSave={(rec) => { if (form === "new") { setMkt((s) => ({ ...s, contacts: [{ id: uid("mc"), created: DEMO_TODAY, lastEngaged: DEMO_TODAY, ...rec }, ...s.contacts] })); logActivity("Marketing", `Contact added: ${rec.name}`); toast("Contact created"); } else { setMkt((s) => ({ ...s, contacts: s.contacts.map((x) => (x.id === form.id ? { ...x, ...rec } : x)) })); toast("Contact updated"); } setForm(null); }} />}</>);
}

/* ───────── Segments ───────── */
const FIELDS: { id: Rule["field"]; label: string; ops: Rule["op"][] }[] = [{ id: "tag", label: "Tag", ops: ["is", "is not"] }, { id: "industry", label: "Industry", ops: ["is", "is not", "contains"] }, { id: "country", label: "Country", ops: ["is", "is not", "contains"] }, { id: "status", label: "Status", ops: ["is", "is not"] }, { id: "list", label: "List", ops: ["is", "is not"] }, { id: "score", label: "Engagement score", ops: ["gte", "lte"] }, { id: "engaged", label: "Last engaged (date)", ops: ["gte", "lte"] }];
const OPL: Record<string, string> = { is: "is", "is not": "is not", contains: "contains", gte: "≥ / on or after", lte: "≤ / on or before" };
function SegmentForm({ existing, onClose }: { existing?: Segment; onClose(): void }) {
  const { mkt, setMkt } = useM(); const toast = useToast(); const [name, setName] = useState(existing?.name ?? ""); const [match, setMatch] = useState<Segment["match"]>(existing?.match ?? "all"); const [rules, setRules] = useState<Rule[]>(existing?.rules ?? [{ field: "tag", op: "is", value: "customer" }]); const [err, setErr] = useState("");
  const seg: Segment = { id: existing?.id ?? "tmp", name, match, rules }; const a = audience(mkt.contacts, seg); const set = (i: number, p: Partial<Rule>) => setRules(rules.map((r, k) => (k === i ? { ...r, ...p } : r)));
  const save = () => { if (name.trim().length < 3) return setErr("Name the segment (3+ characters)."); if (rules.some((r) => !r.value.trim())) return setErr("Every rule needs a value."); if (rules.some((r) => r.field === "score" && !(Number(r.value) >= 0 && Number(r.value) <= 100))) return setErr("Score rules need a number from 0 to 100."); if (mkt.segments.some((s) => s.name.toLowerCase() === name.trim().toLowerCase() && s.id !== existing?.id)) return setErr("A segment with this name already exists.");
    if (existing) setMkt((s) => ({ ...s, segments: s.segments.map((x) => (x.id === existing.id ? { ...x, name: name.trim(), match, rules } : x)) })); else setMkt((s) => ({ ...s, segments: [...s.segments, { id: uid("sg"), name: name.trim(), match, rules }] })); logActivity("Marketing", `Segment saved: ${name.trim()} (${a.members.length} contacts)`); toast(`Segment saved: ${a.members.length} contacts`); onClose(); };
  return (<Modal title={existing ? `Edit segment` : "New segment"} wide onClose={onClose} footer={<><Btn onClick={onClose}>Cancel</Btn><Btn kind="primary" onClick={save} testid="save-segment">Save segment</Btn></>}>
    <div className="grid gap-3 sm:grid-cols-2"><TextIn label="Segment name" value={name} onChange={(e) => setName(e.target.value)} /><SelectIn label="Match" value={match} onChange={(e) => setMatch(e.target.value as Segment["match"])} options={[{ value: "all", label: "ALL of these rules" }, { value: "any", label: "ANY of these rules" }]} /></div>
    <ul className="mt-4 space-y-2" data-testid="rule-list">{rules.map((r, i) => { const f = FIELDS.find((x) => x.id === r.field)!; return <li key={i} className="flex flex-wrap items-center gap-2"><select aria-label="Rule field" value={r.field} onChange={(e) => { const nf = FIELDS.find((x) => x.id === e.target.value)!; set(i, { field: nf.id, op: nf.ops[0], value: "" }); }} className="rounded border border-slate-300 px-2 py-1.5 text-sm">{FIELDS.map((x) => <option key={x.id} value={x.id}>{x.label}</option>)}</select><select aria-label="Rule operator" value={r.op} onChange={(e) => set(i, { op: e.target.value as Rule["op"] })} className="rounded border border-slate-300 px-2 py-1.5 text-sm">{f.ops.map((o) => <option key={o} value={o}>{OPL[o]}</option>)}</select>
      {r.field === "list" ? <select aria-label="Rule value" value={r.value} onChange={(e) => set(i, { value: e.target.value })} className="rounded border border-slate-300 px-2 py-1.5 text-sm"><option value="">Choose list…</option>{mkt.lists.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}</select> : r.field === "status" ? <select aria-label="Rule value" value={r.value} onChange={(e) => set(i, { value: e.target.value })} className="rounded border border-slate-300 px-2 py-1.5 text-sm"><option value="">Choose…</option>{["Subscribed", "Unsubscribed", "Bounced"].map((s) => <option key={s}>{s}</option>)}</select> : <input aria-label="Rule value" type={r.field === "engaged" ? "date" : r.field === "score" ? "number" : "text"} value={r.value} onChange={(e) => set(i, { value: e.target.value })} className="rounded border border-slate-300 px-2 py-1.5 text-sm" />}
      <button type="button" aria-label="Remove rule" className="text-red-600" onClick={() => setRules(rules.filter((_, k) => k !== i))}>✕</button></li>; })}</ul>
    <Btn small className="mt-2" onClick={() => setRules([...rules, { field: "industry", op: "is", value: "" }])} testid="add-rule">+ Add rule</Btn>
    <div className="mt-4 rounded-lg bg-slate-50 p-3 text-sm" data-testid="segment-preview"><b>{a.members.length}</b> contacts match · <b>{a.sendable.length}</b> can receive email · {a.suppressed} suppressed (unsubscribed or bounced)<ul className="mt-1 text-xs text-slate-500">{a.members.slice(0, 4).map((c) => <li key={c.id}>{c.name} · {c.company}</li>)}</ul></div>{err && <p role="alert" className="mt-2 text-sm text-red-600">{err}</p>}</Modal>);
}
function Segments() {
  const { mkt, setMkt } = useM(); const toast = useToast(); const confirm = useConfirm(); const [form, setForm] = useState<Segment | "new" | null>(null);
  return (<><PageHead title="Customer segments" sub="Segments are rule-based and recalculated live from the contact list." actions={<Btn kind="primary" onClick={() => setForm("new")} testid="new-segment">+ New segment</Btn>} />
    <div className="grid gap-3 md:grid-cols-2" data-testid="segment-list">{mkt.segments.map((s) => { const a = audience(mkt.contacts, s); const used = mkt.campaigns.filter((c) => c.segmentId === s.id).length; return <Panel key={s.id} title={s.name} actions={<><Btn small onClick={() => setForm(s)} aria-label={`Edit ${s.name}`}>Edit</Btn><Btn small kind="danger" aria-label={`Delete ${s.name}`} onClick={async () => { if (used) return toast(`${used} campaign(s) use this segment.`, "red"); if (await confirm(`Delete segment ${s.name}?`)) { setMkt((x) => ({ ...x, segments: x.segments.filter((y) => y.id !== s.id) })); toast("Segment deleted", "amber"); } }}>✕</Btn></>}>
      <p className="font-display text-2xl" data-testid={`seg-count-${s.id}`}>{a.members.length}<span className="text-xs text-slate-500"> contacts ({a.sendable.length} sendable)</span></p><p className="mt-1 text-xs text-slate-500">Match {s.match.toUpperCase()}: {s.rules.map((r) => `${FIELDS.find((f) => f.id === r.field)?.label} ${OPL[r.op]} ${r.field === "list" ? mkt.lists.find((l) => l.id === r.value)?.name : r.value}`).join(" · ")}</p><p className="mt-1 text-xs text-slate-400">Used by {used} campaign(s)</p></Panel>; })}</div>
    {form && <SegmentForm existing={form === "new" ? undefined : form} onClose={() => setForm(null)} />}</>);
}

/* ───────── Campaigns ───────── */
/* ───────── Editor ───────── */
function EmailPreview({ t, c, wide }: { t: Template; c: Pick<MContact, "name" | "company" | "industry">; wide: boolean }) {
  return (<div className={`mx-auto overflow-hidden rounded-lg border border-slate-300 bg-slate-100 ${wide ? "max-w-xl" : "max-w-[320px]"}`} data-testid="email-preview">
    <div className="border-b border-slate-300 bg-white px-4 py-2 text-xs"><p className="text-slate-500">From: NorthPeak Team &lt;hello@northpeak-demo.example&gt;</p><p className="font-semibold text-slate-900" data-testid="preview-subject">{merge(t.subject, c) || "(no subject)"}</p><p className="text-slate-400">{merge(t.preheader, c)}</p></div>
    <div className="bg-white px-6 py-6"><div className="mb-4 h-1.5 w-16 rounded bg-blue-600" /><h3 className="font-display text-xl font-semibold text-slate-900">{merge(t.heading, c) || "Heading"}</h3><div className="mt-3 space-y-3 text-sm text-slate-700">{merge(t.body, c).split("\n\n").map((p, i) => <p key={i} className="whitespace-pre-line">{p}</p>)}</div><span className="mt-5 inline-block rounded-md bg-blue-600 px-4 py-2 text-sm font-semibold text-white">{t.cta || "Click here"}</span>
      <p className="mt-6 border-t border-slate-200 pt-3 text-[10px] text-slate-400">You are receiving this because you subscribed to NorthPeak updates. Unsubscribe. Demonstration email with fictional content: it will never be sent.</p></div></div>);
}
function Editor({ id, back }: { id: string; back(): void }) {
  const { mkt, setMkt, segName } = useM(); const toast = useToast(); const confirm = useConfirm(); const c = mkt.campaigns.find((x) => x.id === id); const [tab, setTab] = useState("details"); const [when, setWhen] = useState(c?.scheduledFor || addDays(DEMO_TODAY, 7) + "T09:00"); const [pv, setPv] = useState(""); const [wide, setWide] = useState("desktop"); const [err, setErr] = useState("");
  if (!c) return <Empty>Campaign not found. <Btn small onClick={back}>Back</Btn></Empty>;
  const locked = c.status === "Sent (simulated)"; const aud = campaignAudience(c, mkt.contacts, mkt.segments); const sample = mkt.contacts.find((x) => x.id === pv) ?? aud.sendable[0] ?? mkt.contacts[0]; const unk = unknownFields(c.template);
  const patch = (p: Partial<Campaign>) => setMkt((s) => ({ ...s, campaigns: s.campaigns.map((x) => (x.id === id ? { ...x, ...p } : x)) })); const setT = (p: Partial<Template>) => patch({ template: { ...c.template, ...p } });
  const check = () => { if (c.template.subject.trim().length < 3) return "Add an email subject."; if (c.template.body.trim().length < 10) return "The email body is too short."; if (unk.length) return `Unknown merge field ${unk[0]}. Use ${MERGE_FIELDS.join(", ")}.`; if (aud.sendable.length === 0) return "The selected segment has no contacts who can receive email."; return ""; };
  const schedule = () => { const e = check(); if (e) return setErr(e); if (when < DEMO_NOW) return setErr("Choose a time in the future (the demo clock is 15 Mar 2026, 12:00)."); setErr(""); patch({ status: "Scheduled", scheduledFor: when }); logActivity("Marketing", `Campaign scheduled: ${c.name} for ${fmtDt(when)}`); toast(`Scheduled for ${fmtDt(when)} (simulated: nothing will actually be sent)`); };
  const run = async () => { const e = check(); if (e) return setErr(e); if (!(await confirm(`Run "${c.name}" now as a SIMULATION? It creates an execution history and sample metrics for ${aud.sendable.length} contacts. No email is sent.`, { yes: "Run simulation", danger: false }))) return; setErr("");
    const at = DEMO_NOW.replace("T", " "); const m = simulateMetrics(aud.sendable.length, c.id); const t = (min: number) => at.slice(0, 11) + `${String(12).padStart(2, "0")}:${String(min).padStart(2, "0")}`;
    patch({ status: "Sent (simulated)", scheduledFor: c.scheduledFor && c.status === "Scheduled" ? c.scheduledFor : DEMO_NOW, metrics: m, execution: [{ id: uid("e"), at: t(0), step: "Audience resolved", detail: `${aud.members.length} contacts match “${segName(c.segmentId)}”` }, { id: uid("e"), at: t(0), step: "Suppression applied", detail: `${aud.suppressed} unsubscribed or bounced contacts excluded` }, { id: uid("e"), at: t(1), step: "Template rendered", detail: `Merge fields filled for ${aud.sendable.length} recipients (simulated)` }, { id: uid("e"), at: t(2), step: "Queued (simulated)", detail: "No mail server was contacted" }, { id: uid("e"), at: t(5), step: "Run completed (simulated)", detail: `${m.delivered} delivered, ${m.bounced} bounced: sample figures` }] });
    logActivity("Marketing", `Simulated run: ${c.name} (${aud.sendable.length} recipients)`); toast("Simulated run complete. See the execution history and sample metrics."); setTab("history"); };
  const insert = (f: string) => setT({ body: c.template.body + f });
  return (<><PageHead title={c.name} sub={`${segName(c.segmentId)} · ${aud.sendable.length} sendable contacts`} actions={<><Btn onClick={back}>← Campaigns</Btn><Badge tone={stTone(c.status)}>{c.status}</Badge>
    <Btn onClick={() => { const nid = uid("cp"); setMkt((s) => ({ ...s, campaigns: [{ ...c, id: nid, name: `${c.name} (copy)`, status: "Draft", scheduledFor: "", execution: [], metrics: null, createdAt: DEMO_TODAY }, ...s.campaigns] })); toast("Campaign duplicated as a draft"); }} testid="duplicate">Duplicate</Btn>
    {c.status === "Scheduled" && <Btn kind="danger" onClick={() => { patch({ status: "Cancelled" }); toast("Schedule cancelled", "amber"); }} testid="cancel-schedule">Cancel schedule</Btn>}
    <Btn kind="danger" onClick={async () => { if (await confirm(`Delete campaign "${c.name}"?`)) { setMkt((s) => ({ ...s, campaigns: s.campaigns.filter((x) => x.id !== id) })); toast("Campaign deleted", "amber"); back(); } }}>Delete</Btn></>} />
    {locked && <Notice tone="blue">This campaign has already run (simulated), so it is read-only. Duplicate it to send a new version.</Notice>}
    <div className="mt-3"><Tabs value={tab} onChange={setTab} tabs={[{ id: "details", label: "Details" }, { id: "email", label: "Email template" }, { id: "preview", label: "Preview" }, { id: "run", label: "Schedule & run" }, { id: "history", label: "Execution history", count: c.execution.length }, { id: "metrics", label: "Metrics (simulated)" }]} /></div>
    <div className="mt-3">
      {tab === "details" && <Panel><div className="grid gap-3 sm:grid-cols-2"><TextIn label="Campaign name" disabled={locked} value={c.name} onChange={(e) => patch({ name: e.target.value })} /><SelectIn label="Segment" disabled={locked} value={c.segmentId} onChange={(e) => patch({ segmentId: e.target.value })} options={mkt.segments.map((s) => ({ value: s.id, label: `${s.name} (${audience(mkt.contacts, s).sendable.length})` }))} /><AreaIn label="Description" className="sm:col-span-2" disabled={locked} value={c.description} onChange={(e) => patch({ description: e.target.value })} /></div><p className="mt-3 text-sm text-slate-600" data-testid="audience-line">Audience: <b>{aud.members.length}</b> match · <b>{aud.sendable.length}</b> sendable · {aud.suppressed} suppressed</p></Panel>}
      {tab === "email" && <div className="grid gap-4 xl:grid-cols-2"><Panel title="Email content" actions={<select aria-label="Start from template" disabled={locked} value="" onChange={(ev) => { const t = mkt.templates.find((x) => x.id === ev.target.value); if (t) { patch({ template: { subject: t.subject, preheader: t.preheader, heading: t.heading, body: t.body, cta: t.cta, url: t.url } }); toast(`Applied template “${t.name}”`); } }} className="rounded border border-slate-300 px-2 py-1 text-[15px]"><option value="">Start from template…</option>{mkt.templates.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}</select>}><div className="grid gap-3"><TextIn label="Subject" disabled={locked} value={c.template.subject} onChange={(e) => setT({ subject: e.target.value })} /><TextIn label="Preheader" disabled={locked} value={c.template.preheader} onChange={(e) => setT({ preheader: e.target.value })} /><TextIn label="Heading" disabled={locked} value={c.template.heading} onChange={(e) => setT({ heading: e.target.value })} /><AreaIn label="Body" disabled={locked} rows={7} value={c.template.body} onChange={(e) => setT({ body: e.target.value })} />
        <div className="flex flex-wrap items-center gap-2 text-xs"><span className="text-slate-500">Insert merge field:</span>{MERGE_FIELDS.map((f) => <Btn key={f} small disabled={locked} onClick={() => insert(f)}>{f}</Btn>)}</div>{unk.length > 0 && <p className="text-xs text-red-600">Unknown merge field(s): {unk.join(", ")}</p>}
        <div className="grid gap-3 sm:grid-cols-2"><TextIn label="Button text" disabled={locked} value={c.template.cta} onChange={(e) => setT({ cta: e.target.value })} /><TextIn label="Button link" disabled={locked} value={c.template.url} onChange={(e) => setT({ url: e.target.value })} /></div></div></Panel><Panel title="Live preview (as a sample contact)">{sample && <EmailPreview t={c.template} c={sample} wide />}</Panel></div>}
      {tab === "preview" && <Panel title="Email preview" actions={<><select aria-label="Preview as contact" value={sample?.id} onChange={(e) => setPv(e.target.value)} className="rounded border border-slate-300 px-2 py-1 text-sm">{mkt.contacts.map((x) => <option key={x.id} value={x.id}>{x.name}</option>)}</select><Segmented label="Width" value={wide} onChange={setWide} options={[{ id: "desktop", label: "Desktop" }, { id: "mobile", label: "Mobile" }]} /></>}>{sample && <EmailPreview t={c.template} c={sample} wide={wide === "desktop"} />}<p className="mt-2 text-center text-[11px] text-slate-500">Merge fields are filled for the selected contact. This email is never sent.</p></Panel>}
      {tab === "run" && <Panel title="Schedule or run (simulated)"><Notice>Nothing leaves your browser. Scheduling and running only change this campaign&apos;s status and create a simulated execution history.</Notice>
        <div className="mt-3 flex flex-wrap items-end gap-3"><TextIn label="Send at" type="datetime-local" value={when} onChange={(e) => setWhen(e.target.value)} disabled={locked} /><Btn kind="primary" disabled={locked} onClick={schedule} testid="schedule">Schedule (simulated)</Btn><Btn disabled={locked} onClick={run} testid="run-now">Run simulation now</Btn></div>{err && <p role="alert" className="mt-2 text-sm text-red-600" data-testid="run-error">{err}</p>}</Panel>}
      {tab === "history" && <Panel title="Execution history (simulated)"><Timeline items={[...c.execution].reverse().map((e) => ({ id: e.id, at: e.at, title: e.step, sub: e.detail }))} /></Panel>}
      {tab === "metrics" && <Panel title="Delivery & engagement (simulated)">{c.metrics ? <><Notice>{SIM}</Notice><div className="mt-3"><KpiRow><Kpi label="Recipients" value={c.metrics.recipients} testid="m-rec" /><Kpi label="Delivered" value={c.metrics.delivered} /><Kpi label="Opened (sim.)" value={c.metrics.opened} sub={pct(rate(c.metrics.opened, c.metrics.delivered), 1)} /><Kpi label="Clicked (sim.)" value={c.metrics.clicked} sub={pct(rate(c.metrics.clicked, c.metrics.delivered), 1)} /><Kpi label="Bounced (sim.)" value={c.metrics.bounced} /><Kpi label="Unsubscribed (sim.)" value={c.metrics.unsubscribed} /></KpiRow></div></> : <Empty>No metrics yet. Run the simulation to generate sample figures.</Empty>}</Panel>}
    </div></>);
}

/* ───────── Calendar & analytics ───────── */
function Calendar({ open }: { open(id: string): void }) {
  const { mkt } = useM(); const [month, setMonth] = useState("2026-03"); const [y, m] = month.split("-").map(Number); const first = new Date(Date.UTC(y, m - 1, 1)); const dim = new Date(Date.UTC(y, m, 0)).getUTCDate(); const lead = (first.getUTCDay() + 6) % 7;
  const cells = Array.from({ length: lead + dim }, (_, i) => (i < lead ? null : `${month}-${String(i - lead + 1).padStart(2, "0")}`)); const shift = (d: number) => setMonth(new Date(Date.UTC(y, m - 1 + d, 1)).toISOString().slice(0, 7)); const unscheduled = mkt.campaigns.filter((c) => !c.scheduledFor);
  return (<><PageHead title="Campaign calendar" sub="Scheduled and (simulated) sent campaigns by date." actions={<><Btn onClick={() => shift(-1)}>‹ Prev</Btn><span className="px-2 text-sm font-semibold">{monthLabel(month)}</span><Btn onClick={() => shift(1)}>Next ›</Btn></>} />
    <div className="grid gap-4 lg:grid-cols-[1fr_240px]"><div className="grid grid-cols-7 gap-px overflow-hidden rounded-lg border border-slate-200 bg-slate-200 text-xs" data-testid="calendar">{["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].map((d) => <div key={d} className="bg-slate-50 p-1 text-center font-semibold text-slate-500">{d}</div>)}
      {cells.map((d, i) => <div key={i} className={`min-h-[84px] bg-white p-1 ${d === DEMO_TODAY ? "ring-2 ring-inset ring-blue-500" : ""}`}>{d && <><span className="text-slate-400">{Number(d.slice(8))}</span>{mkt.campaigns.filter((c) => c.scheduledFor.slice(0, 10) === d && c.status !== "Cancelled").map((c) => <button key={c.id} type="button" onClick={() => open(c.id)} className={`mt-0.5 block w-full truncate rounded px-1 text-left ${c.status === "Scheduled" ? "bg-sky-100 text-sky-800" : "bg-blue-100 text-blue-800"}`} title={`${c.name} · ${c.status}`}>{c.name}</button>)}</>}</div>)}</div>
      <Panel title="Unscheduled drafts"><ul className="space-y-1 text-sm">{unscheduled.map((c) => <li key={c.id}><button className="text-blue-700 hover:underline" onClick={() => open(c.id)}>{c.name}</button></li>)}{unscheduled.length === 0 && <li className="text-slate-400">None</li>}</ul><p className="mt-3 text-[11px] text-slate-500"><span className="text-sky-700">■</span> scheduled <span className="ml-2 text-blue-700">■</span> sent (simulated)</p></Panel></div></>);
}
function Analytics({ open }: { open(id: string): void }) {
  const { mkt, segName } = useM(); const [status, setStatus] = useState(""); const sent = mkt.campaigns.filter((c) => c.metrics && (!status || c.status === status));
  const tot = sent.reduce((a, c) => ({ r: a.r + c.metrics!.recipients, d: a.d + c.metrics!.delivered, o: a.o + c.metrics!.opened, c: a.c + c.metrics!.clicked, u: a.u + c.metrics!.unsubscribed, b: a.b + c.metrics!.bounced }), { r: 0, d: 0, o: 0, c: 0, u: 0, b: 0 });
  const cols: Col<Campaign>[] = [{ key: "name", label: "Campaign", render: (c) => <button className="font-medium text-blue-700 hover:underline" onClick={() => open(c.id)}>{c.name}</button>, value: (c) => c.name }, { key: "seg", label: "Segment", value: (c) => segName(c.segmentId) }, { key: "rec", label: "Recipients", align: "right", value: (c) => c.metrics!.recipients }, { key: "del", label: "Delivered", align: "right", value: (c) => c.metrics!.delivered }, { key: "open", label: "Opened (sim.)", align: "right", value: (c) => c.metrics!.opened, render: (c) => `${c.metrics!.opened} (${pct(rate(c.metrics!.opened, c.metrics!.delivered), 1)})` }, { key: "click", label: "Clicked (sim.)", align: "right", value: (c) => c.metrics!.clicked, render: (c) => `${c.metrics!.clicked} (${pct(rate(c.metrics!.clicked, c.metrics!.delivered), 1)})` }, { key: "b", label: "Bounced", align: "right", value: (c) => c.metrics!.bounced }, { key: "u", label: "Unsub.", align: "right", value: (c) => c.metrics!.unsubscribed }];
  const exportAll = () => downloadJson("marketing-report", { disclaimer: SIM, campaigns: mkt.campaigns.map((c) => ({ name: c.name, status: c.status, segment: segName(c.segmentId), scheduledFor: c.scheduledFor, simulatedMetrics: c.metrics, execution: c.execution })), contacts: mkt.contacts.length });
  return (<><PageHead title="Campaign analytics" sub="Only campaigns that have run in the simulation appear here." actions={<><FilterSelect label="Status" value={status} onChange={setStatus} options={["Sent (simulated)"]} /><Btn onClick={exportAll} testid="export-mkt-json">Export JSON</Btn></>} /><Notice>{SIM}</Notice>
    <div className="mt-3"><KpiRow><Kpi label="Campaigns run" value={sent.length} /><Kpi label="Recipients" value={tot.r} testid="an-recipients" /><Kpi label="Open rate (sim.)" value={tot.d ? pct(tot.o / tot.d, 1) : "—"} /><Kpi label="Click rate (sim.)" value={tot.d ? pct(tot.c / tot.d, 1) : "—"} /><Kpi label="Bounce rate (sim.)" value={tot.r ? pct(tot.b / tot.r, 1) : "—"} /></KpiRow></div>
    {sent.length === 0 ? <div className="mt-4"><Empty>No campaign has run yet. Open a campaign and choose “Run simulation now”.</Empty></div> : <><div className="mt-4"><Panel title="Open and click rate by campaign (simulated)"><BarChart ariaLabel="Open and click rates" data={sent.map((c) => ({ label: c.name.split(" ").slice(0, 2).join(" "), values: { open: Math.round(rate(c.metrics!.opened, c.metrics!.delivered) * 1000) / 10, click: Math.round(rate(c.metrics!.clicked, c.metrics!.delivered) * 1000) / 10 } }))} series={[{ key: "open", label: "Open rate % (sim.)" }, { key: "click", label: "Click rate % (sim.)", color: "#f59e0b" }]} fmt={(n) => `${n}%`} /></Panel></div><div className="mt-4"><DataTable rows={sent} columns={cols} rowKey={(c) => c.id} exportName="marketing-campaign-metrics-simulated" search={false} testid="metrics-table" /></div></>}</>);
}

